CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle shown as the publisher of a version. Never reused after deletion, because old tarballs credit it forever.
	"username" VARCHAR(60) NOT NULL UNIQUE,
	-- Contact address for security advisories and ownership transfers.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Publishing is gated on a verified address, which is the cheapest defence against throwaway typosquat accounts.
	"email_verified_at" TIMESTAMPTZ,
	-- False for disabled accounts. Their published versions stay downloadable, because removing them would break every build that depends on them.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A publisher. Accounts are disabled rather than deleted: the registry promises that a version, once published, keeps resolving, and that promise outlives the person who pushed it.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."username" IS 'Public handle shown as the publisher of a version. Never reused after deletion, because old tarballs credit it forever.';
COMMENT ON COLUMN "users"."email" IS 'Contact address for security advisories and ownership transfers.';
COMMENT ON COLUMN "users"."email_verified_at" IS 'Publishing is gated on a verified address, which is the cheapest defence against throwaway typosquat accounts.';
COMMENT ON COLUMN "users"."is_active" IS 'False for disabled accounts. Their published versions stay downloadable, because removing them would break every build that depends on them.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "organizations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The namespace prefix, the acme in @acme/utils. Unique across the registry and claimed once, which is what makes a scoped name unspoofable.
	"scope" VARCHAR(60) NOT NULL UNIQUE,
	-- Human name shown on the organisation page.
	"display_name" VARCHAR(160) NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "organizations" IS 'A claimed namespace. Scopes exist so that publishing under a trusted vendor prefix requires membership rather than only being first to type the name.';
COMMENT ON COLUMN "organizations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "organizations"."scope" IS 'The namespace prefix, the acme in @acme/utils. Unique across the registry and claimed once, which is what makes a scoped name unspoofable.';
COMMENT ON COLUMN "organizations"."display_name" IS 'Human name shown on the organisation page.';
COMMENT ON COLUMN "organizations"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "org_members" (
	-- Organisation joined. Half of the composite primary key.
	"org_id" BIGINT,
	-- Member. The other half of the key.
	"user_id" BIGINT,
	-- owner | admin | member. Only owners can transfer the scope or delete the organisation.
	"role" VARCHAR(16) NOT NULL DEFAULT 'member',
	-- When the member joined.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("org_id", "user_id")
);

COMMENT ON TABLE "org_members" IS 'Membership of a scope. The composite key makes duplicate membership impossible and the reverse index answers which scopes a token may publish to.';
COMMENT ON COLUMN "org_members"."org_id" IS 'Organisation joined. Half of the composite primary key.';
COMMENT ON COLUMN "org_members"."user_id" IS 'Member. The other half of the key.';
COMMENT ON COLUMN "org_members"."role" IS 'owner | admin | member. Only owners can transfer the scope or delete the organisation.';
COMMENT ON COLUMN "org_members"."added_at" IS 'When the member joined.';

CREATE INDEX "idx_org_members_user"
ON "org_members" ("user_id");

CREATE TABLE IF NOT EXISTS "packages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning scope. Null for an unscoped package in the global namespace.
	"org_id" BIGINT,
	-- Full install name including any scope, such as @acme/utils. Unique registry-wide and permanently reserved even after every version is removed, so a deleted name cannot be re-registered by an attacker.
	"name" VARCHAR(214) NOT NULL UNIQUE,
	-- Short summary shown in search results, refreshed from the latest publish rather than edited directly.
	"description" VARCHAR(500),
	-- Project homepage.
	"homepage_url" VARCHAR(1000),
	-- Source repository, and the anchor for provenance and trusted publishing.
	"repository_url" VARCHAR(1000),
	-- SPDX identifier from the latest version. Denormalised so search can filter on licence without joining.
	"license_id" VARCHAR(80),
	-- Private packages resolve only for tokens that can read the owning scope.
	"is_private" BOOLEAN NOT NULL DEFAULT false,
	-- Set when the whole package is deprecated. Printed by the client on install; it does not block resolution, because deprecation is advice, not removal.
	"deprecated_message" VARCHAR(500),
	-- Running total maintained from the daily rollups. Stored because sorting search results by popularity cannot afford to aggregate on every query.
	"downloads_all_time" BIGINT NOT NULL DEFAULT 0,
	-- When the name was first published.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last publish or metadata change, used for the recently-updated feed.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "packages" IS 'The mutable face of a package: name, ownership, description, popularity. Everything a consumer installs lives on a version instead, so changing this row can never change what a build resolves to.';
COMMENT ON COLUMN "packages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "packages"."org_id" IS 'Owning scope. Null for an unscoped package in the global namespace.';
COMMENT ON COLUMN "packages"."name" IS 'Full install name including any scope, such as @acme/utils. Unique registry-wide and permanently reserved even after every version is removed, so a deleted name cannot be re-registered by an attacker.';
COMMENT ON COLUMN "packages"."description" IS 'Short summary shown in search results, refreshed from the latest publish rather than edited directly.';
COMMENT ON COLUMN "packages"."homepage_url" IS 'Project homepage.';
COMMENT ON COLUMN "packages"."repository_url" IS 'Source repository, and the anchor for provenance and trusted publishing.';
COMMENT ON COLUMN "packages"."license_id" IS 'SPDX identifier from the latest version. Denormalised so search can filter on licence without joining.';
COMMENT ON COLUMN "packages"."is_private" IS 'Private packages resolve only for tokens that can read the owning scope.';
COMMENT ON COLUMN "packages"."deprecated_message" IS 'Set when the whole package is deprecated. Printed by the client on install; it does not block resolution, because deprecation is advice, not removal.';
COMMENT ON COLUMN "packages"."downloads_all_time" IS 'Running total maintained from the daily rollups. Stored because sorting search results by popularity cannot afford to aggregate on every query.';
COMMENT ON COLUMN "packages"."created_at" IS 'When the name was first published.';
COMMENT ON COLUMN "packages"."updated_at" IS 'Last publish or metadata change, used for the recently-updated feed.';

CREATE INDEX "idx_packages_org"
ON "packages" ("org_id");
CREATE INDEX "idx_packages_downloads"
ON "packages" ("downloads_all_time");

CREATE TABLE IF NOT EXISTS "package_owners" (
	-- Package owned. Half of the composite primary key.
	"package_id" BIGINT,
	-- Owner. The other half of the key.
	"user_id" BIGINT,
	-- maintainer | publisher. Publishers may push versions; maintainers may also add and remove owners.
	"role" VARCHAR(16) NOT NULL DEFAULT 'maintainer',
	-- Who granted the ownership. Null once that account is gone, but the audit log keeps the full record.
	"added_by_id" BIGINT,
	-- When ownership was granted.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("package_id", "user_id")
);

COMMENT ON TABLE "package_owners" IS 'Direct per-package ownership, which coexists with scope membership rather than replacing it. Unscoped packages have no organisation, so without this table they would have no way to express a second maintainer.';
COMMENT ON COLUMN "package_owners"."package_id" IS 'Package owned. Half of the composite primary key.';
COMMENT ON COLUMN "package_owners"."user_id" IS 'Owner. The other half of the key.';
COMMENT ON COLUMN "package_owners"."role" IS 'maintainer | publisher. Publishers may push versions; maintainers may also add and remove owners.';
COMMENT ON COLUMN "package_owners"."added_by_id" IS 'Who granted the ownership. Null once that account is gone, but the audit log keeps the full record.';
COMMENT ON COLUMN "package_owners"."added_at" IS 'When ownership was granted.';

CREATE INDEX "idx_package_owners_user"
ON "package_owners" ("user_id");

CREATE TABLE IF NOT EXISTS "package_versions" (
	-- Surrogate primary key referenced by dependencies, tags and downloads.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning package.
	"package_id" BIGINT NOT NULL,
	-- Exact semver string as published, such as 2.1.0-beta.3. Never normalised on write, because the string is part of the integrity contract.
	"version" VARCHAR(64) NOT NULL,
	-- Parsed major component. Stored so range resolution and the highest-satisfying query are index scans rather than a parse of every row.
	"major" INTEGER NOT NULL,
	-- Parsed minor component.
	"minor" INTEGER NOT NULL,
	-- Parsed patch component.
	"patch" INTEGER NOT NULL,
	-- Prerelease suffix, empty for a stable release. Null sorts as a stable version, which matches semver precedence rules.
	"prerelease" VARCHAR(64),
	-- Object storage key of the published artifact. Written once and never overwritten; a republish would have to be a new key, which is what makes the bytes immutable in practice and not just by policy.
	"tarball_key" VARCHAR(500) NOT NULL UNIQUE,
	-- Base64 SHA-512 of the tarball, the value clients pin in their lockfiles. It is the reason a version can never be edited: any change to the bytes changes this, and every existing lockfile in the world would start failing.
	"integrity_sha512" CHAR(88) NOT NULL,
	-- Installed size, so the client can warn before an install rather than after.
	"unpacked_bytes" BIGINT NOT NULL,
	-- Compressed artifact size, used for bandwidth accounting.
	"tarball_bytes" BIGINT NOT NULL,
	-- The full package manifest exactly as published, including fields the registry does not interpret. Stored verbatim so the registry can serve what was published rather than its own reconstruction of it.
	"manifest" JSONB NOT NULL,
	-- Rendered documentation snapshot for this version, kept per version so old docs still describe the old API.
	"readme" TEXT,
	-- Publisher at the time. Null only if the account was hard deleted; the audit log retains the name.
	"published_by_id" BIGINT,
	-- Publication instant. Immutable, and the tiebreaker for equal semver precedence.
	"published_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Advisory shown on install for this one version. Set and cleared freely, because it changes no bytes.
	"deprecated_message" VARCHAR(500),
	-- When the version was withdrawn. A yank hides it from range resolution for new installs but keeps it downloadable, so existing lockfiles still build.
	"yanked_at" TIMESTAMPTZ,
	-- Why it was withdrawn, printed by the client so the fix is obvious.
	"yanked_reason" VARCHAR(500),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "package_versions" IS 'An immutable published artifact. Every column that describes the code is frozen at publish; the only mutable fields are the two advisory ones, deprecation and yank, and neither changes what the tarball contains.';
COMMENT ON COLUMN "package_versions"."id" IS 'Surrogate primary key referenced by dependencies, tags and downloads.';
COMMENT ON COLUMN "package_versions"."package_id" IS 'Owning package.';
COMMENT ON COLUMN "package_versions"."version" IS 'Exact semver string as published, such as 2.1.0-beta.3. Never normalised on write, because the string is part of the integrity contract.';
COMMENT ON COLUMN "package_versions"."major" IS 'Parsed major component. Stored so range resolution and the highest-satisfying query are index scans rather than a parse of every row.';
COMMENT ON COLUMN "package_versions"."minor" IS 'Parsed minor component.';
COMMENT ON COLUMN "package_versions"."patch" IS 'Parsed patch component.';
COMMENT ON COLUMN "package_versions"."prerelease" IS 'Prerelease suffix, empty for a stable release. Null sorts as a stable version, which matches semver precedence rules.';
COMMENT ON COLUMN "package_versions"."tarball_key" IS 'Object storage key of the published artifact. Written once and never overwritten; a republish would have to be a new key, which is what makes the bytes immutable in practice and not just by policy.';
COMMENT ON COLUMN "package_versions"."integrity_sha512" IS 'Base64 SHA-512 of the tarball, the value clients pin in their lockfiles. It is the reason a version can never be edited: any change to the bytes changes this, and every existing lockfile in the world would start failing.';
COMMENT ON COLUMN "package_versions"."unpacked_bytes" IS 'Installed size, so the client can warn before an install rather than after.';
COMMENT ON COLUMN "package_versions"."tarball_bytes" IS 'Compressed artifact size, used for bandwidth accounting.';
COMMENT ON COLUMN "package_versions"."manifest" IS 'The full package manifest exactly as published, including fields the registry does not interpret. Stored verbatim so the registry can serve what was published rather than its own reconstruction of it.';
COMMENT ON COLUMN "package_versions"."readme" IS 'Rendered documentation snapshot for this version, kept per version so old docs still describe the old API.';
COMMENT ON COLUMN "package_versions"."published_by_id" IS 'Publisher at the time. Null only if the account was hard deleted; the audit log retains the name.';
COMMENT ON COLUMN "package_versions"."published_at" IS 'Publication instant. Immutable, and the tiebreaker for equal semver precedence.';
COMMENT ON COLUMN "package_versions"."deprecated_message" IS 'Advisory shown on install for this one version. Set and cleared freely, because it changes no bytes.';
COMMENT ON COLUMN "package_versions"."yanked_at" IS 'When the version was withdrawn. A yank hides it from range resolution for new installs but keeps it downloadable, so existing lockfiles still build.';
COMMENT ON COLUMN "package_versions"."yanked_reason" IS 'Why it was withdrawn, printed by the client so the fix is obvious.';

CREATE UNIQUE INDEX "uq_package_versions_pkg_version"
ON "package_versions" ("package_id", "version");
CREATE INDEX "idx_package_versions_semver"
ON "package_versions" ("package_id", "major", "minor", "patch");
CREATE INDEX "idx_package_versions_published"
ON "package_versions" ("package_id", "published_at");

CREATE TABLE IF NOT EXISTS "version_dependencies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The version that declares the dependency.
	"version_id" BIGINT NOT NULL,
	-- Name depended on, stored as a string rather than a foreign key. A manifest may reference a package that is private, removed, or not yet published, and a dangling foreign key would make that publish fail for no good reason.
	"dependency_name" VARCHAR(214) NOT NULL,
	-- Semver range exactly as written, such as ^2.1.0 or >=1.2 <2. Kept verbatim because the client resolver, not the registry, is the authority on what it matches.
	"range_expression" VARCHAR(255) NOT NULL,
	-- runtime | dev | peer | optional. Only runtime dependencies are installed transitively, which is why the distinction has to survive into the registry.
	"kind" VARCHAR(16) NOT NULL DEFAULT 'runtime',
	-- Link to the package when the name is known to this registry. Purely for the dependents graph and advisory fan-out; resolution never uses it.
	"resolved_package_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "version_dependencies" IS 'One declared dependency of one version. Rows rather than a JSON field on the manifest so the reverse question — who depends on this package — is a single index scan, which is what powers dependents counts and advisory notifications.';
COMMENT ON COLUMN "version_dependencies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "version_dependencies"."version_id" IS 'The version that declares the dependency.';
COMMENT ON COLUMN "version_dependencies"."dependency_name" IS 'Name depended on, stored as a string rather than a foreign key. A manifest may reference a package that is private, removed, or not yet published, and a dangling foreign key would make that publish fail for no good reason.';
COMMENT ON COLUMN "version_dependencies"."range_expression" IS 'Semver range exactly as written, such as ^2.1.0 or >=1.2 <2. Kept verbatim because the client resolver, not the registry, is the authority on what it matches.';
COMMENT ON COLUMN "version_dependencies"."kind" IS 'runtime | dev | peer | optional. Only runtime dependencies are installed transitively, which is why the distinction has to survive into the registry.';
COMMENT ON COLUMN "version_dependencies"."resolved_package_id" IS 'Link to the package when the name is known to this registry. Purely for the dependents graph and advisory fan-out; resolution never uses it.';

CREATE INDEX "idx_version_deps_version"
ON "version_dependencies" ("version_id");
CREATE INDEX "idx_version_deps_name"
ON "version_dependencies" ("dependency_name", "kind");

CREATE TABLE IF NOT EXISTS "dist_tags" (
	-- Package the tag belongs to. Half of the composite primary key.
	"package_id" BIGINT,
	-- Tag name such as latest, beta or next. The other half of the key, so a tag points at exactly one version at a time.
	"tag" VARCHAR(64),
	-- Version the tag currently resolves to. Updating this row is the only supported way to change what an unqualified install returns.
	"version_id" BIGINT NOT NULL,
	-- Who last moved the tag.
	"updated_by_id" BIGINT,
	-- When it last moved. Moving latest backwards is a legitimate rollback, so the timestamp is the only record that it happened outside the audit log.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("package_id", "tag")
);

COMMENT ON TABLE "dist_tags" IS 'The mutable pointer layer over immutable versions. Installing a package with no range follows latest, so a bad release is undone by moving a tag rather than by touching a published artifact.';
COMMENT ON COLUMN "dist_tags"."package_id" IS 'Package the tag belongs to. Half of the composite primary key.';
COMMENT ON COLUMN "dist_tags"."tag" IS 'Tag name such as latest, beta or next. The other half of the key, so a tag points at exactly one version at a time.';
COMMENT ON COLUMN "dist_tags"."version_id" IS 'Version the tag currently resolves to. Updating this row is the only supported way to change what an unqualified install returns.';
COMMENT ON COLUMN "dist_tags"."updated_by_id" IS 'Who last moved the tag.';
COMMENT ON COLUMN "dist_tags"."updated_at" IS 'When it last moved. Moving latest backwards is a legitimate rollback, so the timestamp is the only record that it happened outside the audit log.';

CREATE INDEX "idx_dist_tags_version"
ON "dist_tags" ("version_id");

CREATE TABLE IF NOT EXISTS "access_tokens" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning account. A token never outlives its owner.
	"user_id" BIGINT NOT NULL,
	-- What the token is for, such as ci-release. The only way to tell two tokens apart once the secret is gone.
	"name" VARCHAR(120) NOT NULL,
	-- Hash of the secret. The plaintext is shown once at creation and never stored, so a database compromise does not become publish access to the whole registry.
	"token_hash" VARCHAR(255) NOT NULL UNIQUE,
	-- First characters of the token, kept in clear. It is what lets a leaked token found in a public repository be traced back to a row and revoked.
	"token_prefix" CHAR(8) NOT NULL,
	-- read | publish | automation. Automation tokens bypass two-factor prompts, which is why they are a separate kind and not a flag.
	"scope_kind" VARCHAR(16) NOT NULL DEFAULT 'read',
	-- Optional allowlist of package names or scopes this token may write to. Null means every package the owner can publish, which is the setting most incidents start from.
	"package_filter" JSONB,
	-- Expiry. Null for a non-expiring token, which the UI should discourage.
	"expires_at" TIMESTAMPTZ,
	-- Most recent authenticated request. The basis for the unused-token cleanup, and the first thing checked when deciding whether a revocation will break a build.
	"last_used_at" TIMESTAMPTZ,
	-- Revocation time. Kept rather than deleted so an audit row naming this token still resolves.
	"revoked_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "access_tokens" IS 'A credential that can publish. Storing only a hash plus a traceable prefix is the difference between a leaked token being revoked in minutes and a registry-wide supply chain incident.';
COMMENT ON COLUMN "access_tokens"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "access_tokens"."user_id" IS 'Owning account. A token never outlives its owner.';
COMMENT ON COLUMN "access_tokens"."name" IS 'What the token is for, such as ci-release. The only way to tell two tokens apart once the secret is gone.';
COMMENT ON COLUMN "access_tokens"."token_hash" IS 'Hash of the secret. The plaintext is shown once at creation and never stored, so a database compromise does not become publish access to the whole registry.';
COMMENT ON COLUMN "access_tokens"."token_prefix" IS 'First characters of the token, kept in clear. It is what lets a leaked token found in a public repository be traced back to a row and revoked.';
COMMENT ON COLUMN "access_tokens"."scope_kind" IS 'read | publish | automation. Automation tokens bypass two-factor prompts, which is why they are a separate kind and not a flag.';
COMMENT ON COLUMN "access_tokens"."package_filter" IS 'Optional allowlist of package names or scopes this token may write to. Null means every package the owner can publish, which is the setting most incidents start from.';
COMMENT ON COLUMN "access_tokens"."expires_at" IS 'Expiry. Null for a non-expiring token, which the UI should discourage.';
COMMENT ON COLUMN "access_tokens"."last_used_at" IS 'Most recent authenticated request. The basis for the unused-token cleanup, and the first thing checked when deciding whether a revocation will break a build.';
COMMENT ON COLUMN "access_tokens"."revoked_at" IS 'Revocation time. Kept rather than deleted so an audit row naming this token still resolves.';
COMMENT ON COLUMN "access_tokens"."created_at" IS 'Creation time.';

CREATE INDEX "idx_access_tokens_user"
ON "access_tokens" ("user_id", "revoked_at");

CREATE TABLE IF NOT EXISTS "version_downloads" (
	-- Version downloaded. Half of the composite primary key.
	"version_id" BIGINT,
	-- UTC day of the counts. The other half of the key, which makes the upsert from the log pipeline idempotent and safe to replay.
	"day" DATE,
	-- Denormalised owner so per-package charts read one index without joining to versions.
	"package_id" BIGINT NOT NULL,
	-- Requests counted for that version on that day, already deduplicated by the ingest pipeline so a CI cache miss storm does not read as popularity.
	"download_count" BIGINT NOT NULL DEFAULT 0,
	PRIMARY KEY("version_id", "day")
);

COMMENT ON TABLE "version_downloads" IS 'Daily rollups rather than one row per request. Download counts are read constantly and needed only at day granularity, and a pre-aggregated grain keeps the popularity graph a range scan instead of a sum over billions of rows.';
COMMENT ON COLUMN "version_downloads"."version_id" IS 'Version downloaded. Half of the composite primary key.';
COMMENT ON COLUMN "version_downloads"."day" IS 'UTC day of the counts. The other half of the key, which makes the upsert from the log pipeline idempotent and safe to replay.';
COMMENT ON COLUMN "version_downloads"."package_id" IS 'Denormalised owner so per-package charts read one index without joining to versions.';
COMMENT ON COLUMN "version_downloads"."download_count" IS 'Requests counted for that version on that day, already deduplicated by the ingest pipeline so a CI cache miss storm does not read as popularity.';

CREATE INDEX "idx_version_downloads_package_day"
ON "version_downloads" ("package_id", "day");

CREATE TABLE IF NOT EXISTS "registry_audit_log" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Package affected. Null for account and organisation level events.
	"package_id" BIGINT,
	-- Version affected, for publish, yank and deprecate actions.
	"version_id" BIGINT,
	-- Who acted. Null for automated actions such as an advisory-driven yank.
	"actor_id" BIGINT,
	-- Token used, when the action came through the API. Knowing which credential published a compromised version is the first question asked in a supply chain incident.
	"token_id" BIGINT,
	-- version_published | version_yanked | version_deprecated | tag_moved | owner_added | owner_removed | package_transferred | token_revoked.
	"action" VARCHAR(40) NOT NULL,
	-- Action-specific payload: the tag and both versions for a tag move, the reason for a yank.
	"details" JSONB,
	-- Source address of the request. Retained briefly for incident response, which is the only reason it is here.
	"actor_ip" INET,
	-- When it happened.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "registry_audit_log" IS 'Append-only history of everything that changes what consumers resolve. Because versions are immutable, this log plus the tag pointers is a complete explanation of any change a user could have observed.';
COMMENT ON COLUMN "registry_audit_log"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "registry_audit_log"."package_id" IS 'Package affected. Null for account and organisation level events.';
COMMENT ON COLUMN "registry_audit_log"."version_id" IS 'Version affected, for publish, yank and deprecate actions.';
COMMENT ON COLUMN "registry_audit_log"."actor_id" IS 'Who acted. Null for automated actions such as an advisory-driven yank.';
COMMENT ON COLUMN "registry_audit_log"."token_id" IS 'Token used, when the action came through the API. Knowing which credential published a compromised version is the first question asked in a supply chain incident.';
COMMENT ON COLUMN "registry_audit_log"."action" IS 'version_published | version_yanked | version_deprecated | tag_moved | owner_added | owner_removed | package_transferred | token_revoked.';
COMMENT ON COLUMN "registry_audit_log"."details" IS 'Action-specific payload: the tag and both versions for a tag move, the reason for a yank.';
COMMENT ON COLUMN "registry_audit_log"."actor_ip" IS 'Source address of the request. Retained briefly for incident response, which is the only reason it is here.';
COMMENT ON COLUMN "registry_audit_log"."created_at" IS 'When it happened.';

CREATE INDEX "idx_registry_audit_package_time"
ON "registry_audit_log" ("package_id", "created_at");
CREATE INDEX "idx_registry_audit_actor_time"
ON "registry_audit_log" ("actor_id", "created_at");

