ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "org_members"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "packages"
ADD FOREIGN KEY("org_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "package_owners"
ADD FOREIGN KEY("package_id") REFERENCES "packages"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "package_owners"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "package_owners"
ADD FOREIGN KEY("added_by_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "package_versions"
ADD FOREIGN KEY("package_id") REFERENCES "packages"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "package_versions"
ADD FOREIGN KEY("published_by_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "version_dependencies"
